    static final long MOD = 1_000_000_007L;

    static class Spell implements Comparable<Spell> {
        long a, b;

        Spell(long a, long b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public int compareTo(Spell o) {
            if (this.a != o.a) {
                return Long.compare(this.a, o.a);
            }
            return Long.compare(this.b, o.b);
        }
    }

    static class Meal implements Comparable<Meal> {
        long a, b;

        Meal(long a, long b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public int compareTo(Meal o) {
            // Compare b1 * (a2 - 1) with b2 * (a1 - 1)
            long v1 = this.b * (o.a - 1);
            long v2 = o.b * (this.a - 1);
            return Long.compare(v2, v1); // Descending order
        }
    }

    static long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long modInverse(long n) {
        return power(n, MOD - 2);
    }

    static long applyPower(long a, long b, long k, long x) {
        if (k == 0) return x % MOD;
        if (a == 1) {
            long add = ((k % MOD) * (b % MOD)) % MOD;
            return (x + add) % MOD;
        }
        long a_pow_k = power(a, k);
        long term1 = (a_pow_k * (x % MOD)) % MOD;
        long num = (a_pow_k - 1 + MOD) % MOD;
        long den = modInverse(a - 1);
        long geom = (num * den) % MOD;
        long term2 = (geom * (b % MOD)) % MOD;
        return (term1 + term2) % MOD;
    }

    // Upper envelope lines and transition thresholds
    static long[] hullA;
    static long[] hullB;
    static long[] T;
